struct key *construct_and_link_key(struct keyring_search_context *ctx,
                                   const char *callout_info,
                                   size_t callout_len,
                                   void *aux,
                                   struct key *dest_keyring,
                                   unsigned long flags) {
    struct key *key = NULL;
    struct key *target_keyring = NULL;
    struct user_struct *current_user;
    int ret;

    if (!ctx || !dest_keyring) {
        return ERR_PTR(-EINVAL);
    }

    target_keyring = lookup_keyring(ctx);
    if (IS_ERR(target_keyring)) {
        return target_keyring;
    }

    current_user = get_current_user();
    if (!current_user) {
        key_put(target_keyring);
        return ERR_PTR(-ENOMEM);
    }

    key = key_alloc(target_keyring->type, callout_info, callout_len, current_user, flags, NULL);
    if (IS_ERR(key)) {
        put_user(current_user);
        key_put(target_keyring);
        return key;
    }

    ret = key_instantiate_and_link(key, aux, callout_len, dest_keyring, NULL);
    if (ret < 0) {
        key_put(key);
        put_user(current_user);
        key_put(target_keyring);
        return ERR_PTR(ret);
    }

    put_user(current_user);
    key_put(target_keyring);

    return key;
}

struct key *construct_and_link_key(struct keyring_search_context *ctx,
                                   const char *callout_info,
                                   size_t callout_len,
                                   void *aux,
                                   struct key *dest_keyring,
                                   unsigned long flags) {
    struct key *key = NULL;
    struct user_struct *user = NULL;
    int ret;

    if (!ctx || !dest_keyring) {
        return ERR_PTR(-EINVAL);
    }

    ret = keyring_search_verify(ctx);
    if (ret < 0) {
        return ERR_PTR(ret);
    }

    user = get_current_user();
    if (!user) {
        return ERR_PTR(-ENOMEM);
    }

    key = key_alloc(&key_type_user, callout_info, callout_len, user, flags, 0);
    if (IS_ERR(key)) {
        put_user(user);
        return key;
    }

    ret = key_instantiate_and_link(key, callout_info, callout_len, aux, dest_keyring);
    if (ret < 0) {
        key_revoke(key);
        key_put(key);
        put_user(user);
        return ERR_PTR(ret);
    }

    put_user(user);
    return key;
}

struct key *construct_and_link_key(struct keyring_search_context *ctx,
                                   const char *callout_info,
                                   size_t callout_len,
                                   void *aux,
                                   struct key *dest_keyring,
                                   unsigned long flags) {
    struct key *key = NULL;
    struct user_struct *user = NULL;
    int ret;

    /* Check if the destination keyring is valid */
    if (!S_ISKEY(dest_keyring)) {
        return ERR_PTR(-EINVAL);
    }

    /* Retrieve the current user */
    user = get_current_user();
    if (!user) {
        return ERR_PTR(-ENOMEM);
    }

    /* Allocate a new key structure */
    key = alloc_key();
    if (!key) {
        put_user(user);
        return ERR_PTR(-ENOMEM);
    }

    /* Initialize the key with the given callout info */
    ret = key->type->instantiate(key, callout_info, callout_len, aux);
    if (ret < 0) {
        put_user(user);
        free_key(key);
        return ERR_PTR(ret);
    }

    /* Link the key to the destination keyring */
    ret = keyring_link(dest_keyring, key);
    if (ret < 0) {
        put_user(user);
        key_invalidate(key);
        free_key(key);
        return ERR_PTR(ret);
    }

    key->user = user;
    return key;
}

struct key *construct_and_link_key(struct keyring_search_context *ctx,
                                   const char *callout_info,
                                   size_t callout_len,
                                   void *aux,
                                   struct key *dest_keyring,
                                   unsigned long flags) {
    struct key *key = NULL;
    struct key *target_keyring = NULL;
    struct user_struct *current_user = NULL;
    int ret;

    if (!ctx || !dest_keyring) {
        return ERR_PTR(-EINVAL);
    }

    target_keyring = lookup_keyring(ctx);
    if (IS_ERR(target_keyring)) {
        return target_keyring;
    }

    current_user = get_current_user();
    if (!current_user) {
        ret = -ENOMEM;
        goto error;
    }

    key = alloc_key(target_keyring, flags);
    if (IS_ERR(key)) {
        ret = PTR_ERR(key);
        key = NULL;
        goto error;
    }

    ret = construct_key(key, callout_info, callout_len, aux);
    if (ret < 0) {
        goto error;
    }

    ret = link_key(key, dest_keyring);
    if (ret < 0) {
        goto error;
    }

    return key;

error:
    if (key) {
        free_key(key);
    }

    if (target_keyring) {
        put_key(target_keyring);
    }

    if (current_user) {
        put_user(current_user);
    }

    return ERR_PTR(ret);
}

struct key *construct_and_link_key(struct keyring_search_context *ctx,
                                   const char *callout_info,
                                   size_t callout_len,
                                   void *aux,
                                   struct key *dest_keyring,
                                   unsigned long flags) {
    struct key *new_key = NULL;
    struct key *index_key = NULL;
    struct key *keyring = NULL;
    struct user_struct *current_user = NULL;
    int ret = 0;

    if (!dest_keyring) {
        return ERR_PTR(-EINVAL);
    }

    index_key = keyring_search(ctx, NULL, NULL);
    if (IS_ERR(index_key)) {
        return index_key;
    }

    keyring = key_get(dest_keyring);
    if (!keyring) {
        ret = -ENOMEM;
        goto error;
    }

    current_user = get_current_user();
    if (!current_user) {
        ret = -ENOMEM;
        goto error;
    }

    new_key = key_alloc(index_key->type, callout_info, callout_len, current_user, 0, 0, flags);
    if (IS_ERR(new_key)) {
        new_key = ERR_CAST(new_key);
        ret = PTR_ERR(new_key);
        goto error;
    }

    ret = key_instantiate_and_link(new_key, aux, callout_len, keyring, NULL);
    if (ret < 0) {
        key_put(new_key);
        new_key = ERR_PTR(ret);
        goto error;
    }

    key_put(keyring);
    key_put(index_key);
    return new_key;

error:
    key_put(keyring);
    key_put(index_key);
    return ERR_PTR(ret);
}
